import ProductCard from './ProductCard';

function ProductList({ products, onAdd, onDelete }) {
  if (!products.length) return <p className="empty-state">No products found.</p>;

  return (
    <div className="product-grid">
      {products.map((product) => <ProductCard key={product.id} product={product} onAdd={onAdd} onDelete={onDelete} />)}
    </div>
  );
}

export default ProductList;
